#include <stdio.h>

int maximum(int a, int b) { return a > b ? a : b; }

int main(void) {
    int a, b, c, d;
    scanf("%d%d%d%d", &a, &b, &c, &d);
    printf("%d\n", maximum(maximum(a, b), maximum(c, d)));
    return 0;
}
